// Golden tests for the crease-pattern entities (OriPoint, OriLine, OriPolygon) and the grid
// (GridManager + square/triangle grid points/lines/render data).
// Goldens generated by tools/fixtures/core/model.js from the reference JS implementation.
import Foundation
import ORIPACore

private struct ModelFixture: Decodable {
    struct GetKeyCase: Decodable {
        let value: Double
        let key: Int
    }

    struct PointJSON: Decodable {
        let x: Double
        let y: Double
        let xKey: Int
        let yKey: Int
        let hash: Int
        let equalsEqual: Int
        let equalsDifferent: Int
        let copyEquals: Int
        let copyIsSameObject: Int
        let occurrenceCount: Int
        let lineTypeCount: [Int]
        let floatArray: [Double]
        let pointDoubleHash: Int
    }

    struct CompareCase: Decodable {
        let a: [Double]
        let b: [Double]
        let result: Int
    }

    struct LineJSON: Decodable {
        let input: [Double]
        let ordered: [Double]
        let type: Int
        let hash: Int
        let floatArray: [Double]
        let copyEquals: Int
        let copyIsSameObject: Int
        let copyPointsDistinct: Int
        let diagonalStart: [Double]
        let diagonalEnd: [Double]
        let diagonalOrdered: [Double]
        let reversedConstructorEquals: Int
        let noSortInput: [Double]
    }

    struct ContainsCase: Decodable {
        let point: [Double]
        let result: Int
    }

    struct LineTypeChange: Decodable {
        let type: Int
        let startMountain: Int
        let startValley: Int
    }

    struct PolygonJSON: Decodable {
        let points: [[Double]]
        let lineTypes: [Int]
        let area: Double
        let centroid: [Double]
    }

    struct PointNearestJSON: Decodable {
        let point: [Double]?
        let distance: Double
    }

    struct LineNearestJSON: Decodable {
        let line: [Double]?
        let distance: Double
    }

    struct GridQuery: Decodable {
        let point: [Double]
        let radius: Double
        let result: PointNearestJSON
    }

    struct LineQuery: Decodable {
        let point: [Double]
        let radius: Double
        let result: LineNearestJSON
    }

    struct UpdateCase: Decodable {
        let division: Int
        let type: Int
        let result: Int
    }

    struct SquareGrid: Decodable {
        let defaultDivision: Int
        let defaultGridType: Int
        let findPoints: [GridQuery]
        let lineQueries: [LineQuery]
        let updates: [UpdateCase]
    }

    struct TriangleGrid: Decodable {
        let findPoints: [GridQuery]
        let lineQueries: [LineQuery]
    }

    struct RenderDataJSON: Decodable {
        let vertexPosition: [Double]
        let vertexAngleDeg: [Int]
        let drawOrder: [Int]
    }

    struct GridJSON: Decodable {
        let square: SquareGrid
        let squareRenderData4: RenderDataJSON
        let squareRenderData3: RenderDataJSON
        let triangle: TriangleGrid
        let triangleRenderData3: RenderDataJSON
    }

    let getKeyCases: [GetKeyCase]
    let points: [PointJSON]
    let compareCases: [CompareCase]
    let lines: [LineJSON]
    let containsInRange: [ContainsCase]
    let lineTypeChange: LineTypeChange
    let polygons: [PolygonJSON]
    let grid: GridJSON
}

private func expectPointNearest(_ harness: TestHarness, _ actual: NearestItem<OriPoint>,
                                _ expected: ModelFixture.PointNearestJSON, _ label: String) {
    if let expectedPoint = expected.point {
        harness.expectNotNil(actual.nearestItem, "\(label).item")
        if let item = actual.nearestItem {
            harness.expectClose(item.x, expectedPoint[0], accuracy: 1e-9, "\(label).x")
            harness.expectClose(item.y, expectedPoint[1], accuracy: 1e-9, "\(label).y")
        }
    } else {
        harness.expectNil(actual.nearestItem, "\(label).item nil")
    }
    harness.expectClose(actual.distance, expected.distance, accuracy: 1e-9, "\(label).distance")
}

private func expectLineNearest(_ harness: TestHarness, _ actual: NearestItem<OriLine>,
                               _ expected: ModelFixture.LineNearestJSON, _ label: String) {
    if let expectedLine = expected.line {
        harness.expectNotNil(actual.nearestItem, "\(label).item")
        if let item = actual.nearestItem {
            expectCloseArray(harness, CoreModelJSON.lineValues(item), expectedLine, accuracy: 1e-9, "\(label).line")
        }
    } else {
        harness.expectNil(actual.nearestItem, "\(label).item nil")
    }
    harness.expectClose(actual.distance, expected.distance, accuracy: 1e-9, "\(label).distance")
}

private func expectRenderData(_ harness: TestHarness, _ actual: GridRenderData,
                              _ expected: ModelFixture.RenderDataJSON, _ label: String) {
    expectCloseArray(harness, actual.vertexPosition.map(Double.init), expected.vertexPosition,
                     accuracy: 1e-9, "\(label).vertexPosition")
    expectEqualArray(harness, actual.vertexAngleDeg.map(Int.init), expected.vertexAngleDeg,
                     "\(label).vertexAngleDeg")
    expectEqualArray(harness, actual.drawOrder.map(Int.init), expected.drawOrder, "\(label).drawOrder")
}

enum ModelTests {
    static var all: [TestSuite] {
        [TestSuite("CoreModel.Model") { harness in
            let fixture = try Fixtures.decode(ModelFixture.self, "Fixtures/core/model.json")

            // MARK: OriPoint.getKey
            for entry in fixture.getKeyCases {
                harness.expectEqual(OriPoint.getKey(entry.value), entry.key, "OriPoint.getKey(\(entry.value))")
            }

            // MARK: OriPoint
            for pointFixture in fixture.points {
                let point = OriPoint(pointFixture.x, pointFixture.y)
                harness.expectEqual(point.xKey, pointFixture.xKey, "OriPoint.xKey (\(pointFixture.x))")
                harness.expectEqual(point.yKey, pointFixture.yKey, "OriPoint.yKey (\(pointFixture.y))")
                harness.expectEqual(point.hashCode(), pointFixture.hash, "OriPoint.hashCode (\(pointFixture.x))")
                harness.expectEqual(
                    boolValue(point.equals(OriPoint(pointFixture.x, pointFixture.y))),
                    pointFixture.equalsEqual, "OriPoint.equals equal"
                )
                harness.expectEqual(
                    boolValue(point.equals(OriPoint(pointFixture.x + 100, pointFixture.y))),
                    pointFixture.equalsDifferent, "OriPoint.equals different"
                )
                let copy = point.copy()
                harness.expectEqual(boolValue(copy.equals(point)), pointFixture.copyEquals, "OriPoint.copy equals")
                harness.expectEqual(boolValue(copy === point), pointFixture.copyIsSameObject, "OriPoint.copy identity")
                harness.expectEqual(point.getOccurrenceCount(), pointFixture.occurrenceCount, "OriPoint occurrence")
                expectEqualArray(harness, Array(point.getAllLineTypeCount().prefix(4)), pointFixture.lineTypeCount,
                                 "OriPoint lineTypeCount")
                expectCloseArray(harness, point.toFloatArray().map(Double.init), pointFixture.floatArray,
                                 "OriPoint.toFloatArray")
                harness.expectEqual(PointDouble(pointFixture.x, pointFixture.y).hashCode(),
                                    pointFixture.pointDoubleHash, "PointDouble.hashCode (same coords)")
            }

            // MARK: compareTo
            for entry in fixture.compareCases {
                let actual = OriPoint(entry.a[0], entry.a[1]).compareTo(OriPoint(entry.b[0], entry.b[1]))
                harness.expectEqual(actual, entry.result,
                                    "compareTo(\(entry.a)) vs (\(entry.b))")
            }

            // MARK: OriLine
            for lineFixture in fixture.lines {
                let values = lineFixture.input
                let line = OriLine(OriPoint(values[0], values[1]), OriPoint(values[2], values[3]),
                                   Int(values[4]))
                expectCloseArray(harness, CoreModelJSON.lineValues(line), lineFixture.ordered, "OriLine ordered")
                harness.expectEqual(line.typeValue, lineFixture.type, "OriLine type")
                harness.expectEqual(line.hashCode(), lineFixture.hash, "OriLine hashCode")
                expectCloseArray(harness, line.toFloatArray().map(Double.init), lineFixture.floatArray,
                                 "OriLine toFloatArray")
                harness.expectEqual(boolValue(line.copy().equals(line)), lineFixture.copyEquals, "OriLine copy equals")
                harness.expectEqual(boolValue(line.copy() === line), lineFixture.copyIsSameObject,
                                    "OriLine copy identity")
                let copy = line.copy()
                harness.expectEqual(boolValue(copy.start !== line.start && copy.end !== line.end),
                                    lineFixture.copyPointsDistinct, "OriLine copy points distinct")
                let diagonal = line.diagonalCopy()
                expectCloseArray(harness, [diagonal.start.x, diagonal.start.y], lineFixture.diagonalStart,
                                 "OriLine diagonalStart")
                expectCloseArray(harness, [diagonal.end.x, diagonal.end.y], lineFixture.diagonalEnd,
                                 "OriLine diagonalEnd")
                expectCloseArray(harness, CoreModelJSON.lineValues(diagonal), lineFixture.diagonalOrdered,
                                 "OriLine diagonal ordered")
                let reversed = OriLine(OriPoint(values[2], values[3]), OriPoint(values[0], values[1]), Int(values[4]))
                harness.expectEqual(boolValue(reversed.equals(line)), lineFixture.reversedConstructorEquals,
                                    "OriLine reversed constructor equals")
                let unsorted = OriLine(OriPoint(values[0], values[1]), OriPoint(values[2], values[3]),
                                       Int(values[4]), true)
                expectCloseArray(harness, [unsorted.start.x, unsorted.start.y, unsorted.end.x, unsorted.end.y],
                                 lineFixture.noSortInput, "OriLine ignoreOrder")
            }

            // MARK: containsInRange
            let horizontal = OriLine(OriPoint(0, 0), OriPoint(100, 0), 2)
            for entry in fixture.containsInRange {
                let point = OriPoint(entry.point[0], entry.point[1])
                harness.expectEqual(boolValue(horizontal.containsInRange(point)), entry.result,
                                    "OriLine.containsInRange(\(entry.point))")
            }

            // MARK: setType keeps endpoint counters
            let changing = OriLine(OriPoint(0, 0), OriPoint(100, 0), 2)
            let startPoint = changing.start
            changing.setType(.valley)
            harness.expectEqual(changing.typeValue, fixture.lineTypeChange.type, "setType line type")
            harness.expectEqual(startPoint.getLineTypeCount(.mountain), fixture.lineTypeChange.startMountain,
                                "setType start mountain count")
            harness.expectEqual(startPoint.getLineTypeCount(.valley), fixture.lineTypeChange.startValley,
                                "setType start valley count")
            // Setting through the `lineType` property routes through `setType`; the initial
            // constructor does not register counters (points are registered by the tree), so
            // mountain goes -1 -> 0 and valley 1 -> 0 like the reference.
            changing.lineType = .mountain
            harness.expectEqual(changing.typeValue, 2, "lineType setter")
            harness.expectEqual(startPoint.getLineTypeCount(.mountain), 0, "lineType setter mountain counter")
            harness.expectEqual(startPoint.getLineTypeCount(.valley), 0, "lineType setter valley counter")

            // MARK: OriPolygon
            for polygonFixture in fixture.polygons {
                let polygon = OriPolygon()
                for point in polygonFixture.points {
                    polygon.points.append(OriPoint(point[0], point[1]))
                }
                polygon.lineTypes = polygonFixture.lineTypes
                harness.expectClose(polygon.getArea(), polygonFixture.area, accuracy: 1e-9, "OriPolygon area")
                let centroid = polygon.getCentroid()
                expectCloseArray(harness, [centroid.x, centroid.y], polygonFixture.centroid,
                                 "OriPolygon centroid")
                harness.expectEqual(polygon.points.count, polygonFixture.points.count, "OriPolygon point count")
                harness.expectEqual(polygon.lineTypes, polygonFixture.lineTypes, "OriPolygon line types")
            }

            // MARK: GridManager (square)
            let manager = GridManager(200)
            harness.expectEqual(manager.getDivisionNumber(), fixture.grid.square.defaultDivision,
                                "grid default division")
            harness.expectEqual(manager.getGridType().rawValue, fixture.grid.square.defaultGridType,
                                "grid default type")
            for query in fixture.grid.square.findPoints {
                let nearest = manager.findPoint(PointDouble(query.point[0], query.point[1]), query.radius)
                expectPointNearest(harness, nearest, query.result, "grid square findPoint \(query.point)")
            }
            for query in fixture.grid.square.lineQueries {
                let nearest = manager.findLine(PointDouble(query.point[0], query.point[1]), query.radius)
                expectLineNearest(harness, nearest, query.result, "grid square findLine \(query.point)")
            }
            for update in fixture.grid.square.updates {
                let result: Int
                do {
                    result = try manager.update(update.division, update.type) ? 1 : 0
                } catch {
                    result = -1
                }
                harness.expectEqual(result, update.result, "grid update(\(update.division),\(update.type))")
            }

            // MARK: grid render data
            let square4 = GridManager(200)
            expectRenderData(harness, square4.getRenderData(), fixture.grid.squareRenderData4, "square4")
            let square3 = GridManager(200)
            try square3.update(3, GridType.square)
            expectRenderData(harness, square3.getRenderData(), fixture.grid.squareRenderData3, "square3")

            // MARK: triangle grid
            let triangle = GridManager(200)
            try triangle.update(4, GridType.triangle)
            harness.expectEqual(triangle.getGridType(), .triangle, "triangle grid type")
            harness.expectEqual(triangle.getDivisionNumber(), 4, "triangle grid division")
            for query in fixture.grid.triangle.findPoints {
                let nearest = triangle.findPoint(PointDouble(query.point[0], query.point[1]), query.radius)
                expectPointNearest(harness, nearest, query.result, "grid triangle findPoint \(query.point)")
            }
            for query in fixture.grid.triangle.lineQueries {
                let nearest = triangle.findLine(PointDouble(query.point[0], query.point[1]), query.radius)
                expectLineNearest(harness, nearest, query.result, "grid triangle findLine \(query.point)")
            }
            let triangle3 = GridManager(200)
            try triangle3.update(3, GridType.triangle)
            expectRenderData(harness, triangle3.getRenderData(), fixture.grid.triangleRenderData3, "triangle3")
        }]
    }
}
